package mz.bam.seeky.android;
import android.app.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class,qualifiers="w360dp-h800dp-mdpi",shadows={ReferenceDesign5150Test.LocalStorage.class}) @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class Categories5160Test {
 ReferenceDesign5150Test f;MainActivity a;
 @Before public void setup()throws Exception{f=new ReferenceDesign5150Test();f.before();a=f.a;}
 @After public void close()throws Exception{f.after();}
 @Test public void referenceGridHasFourColumnsAndNineCentredCategoryActions()throws Exception{assertEquals(4,a.homeCategories.columns);assertEquals(9,a.homeCategories.cards.size());assertEquals(3,a.homeCategories.getChildCount());for(int i=0;i<9;i++){LinearLayout card=a.homeCategories.cards.get(i);assertEquals(LinearLayout.VERTICAL,card.getOrientation());assertEquals(Gravity.CENTER_HORIZONTAL,a.homeCategories.titles.get(i).getGravity()&Gravity.HORIZONTAL_GRAVITY_MASK);assertTrue(((ViewGroup)card.getChildAt(0)).getChildAt(0) instanceof CategoryIcon);}assertEquals("ZIPs",a.homeCategories.titles.get(5).getText().toString());assertEquals("APKs",a.homeCategories.titles.get(6).getText().toString());f.capture(a.shell,"categorias-5160",360,800);}
 @Test public void fileActionsKeepTheirOriginalCategoryAndCounts()throws Exception{a.homeCategories.cards.get(5).performClick();assertEquals("Pesquisa",a.tab);assertEquals("Arquivos",a.category);a.tab="Início";a.render();f.drain();a.homeCategories.cards.get(6).performClick();assertEquals("Aplicações",a.category);}
 @Test @Config(qualifiers="w288dp-h640dp-mdpi") public void narrowScreenUsesThreeColumnsAndKeepsLargerIconsReadable()throws Exception{assertEquals(3,a.homeCategories.columns);IconSizing.set(a,"icon_size",2);a.render();f.drain();f.capture(a.shell,"categorias-estreitas-5160",288,640);for(TextView title:a.homeCategories.titles){assertNotNull(title.getLayout());for(int i=0;i<title.getLineCount();i++)assertEquals(title.getText().toString(),0,title.getLayout().getEllipsisCount(i));}}
 @Test public void illustrationsHaveDistinctColoursAndTransparentCorners(){int[] centre=new int[9];for(int i=0;i<9;i++){CategoryIcon icon=new CategoryIcon(a,HomeCategories.NAMES[i]);icon.layout(0,0,48,48);Bitmap b=Bitmap.createBitmap(48,48,Bitmap.Config.ARGB_8888);icon.draw(new Canvas(b));assertEquals(0,Color.alpha(b.getPixel(0,0)));int coloured=0;for(int y=4;y<44;y++)for(int x=4;x<44;x++)if(Color.alpha(b.getPixel(x,y))>0)coloured++;assertTrue(HomeCategories.NAMES[i],coloured>400);b.recycle();}}
 @Test public void sharedActionCardsActuallyShowTheirExplanatoryText(){LinearLayout parent=a.column();a.actionCard(parent,"book","Continuar a estudar","Biologia · 37%",()->{});assertNotNull(VoiceToolsTest.findText(parent,"Biologia · 37%"));}
}
